-- 0003: Seed secure public token for existing INT-001 and any questionnaires without token
-- Idempotent: only inserts where token missing. Token must be generated by Worker, not here.
-- This file only ensures placeholder logic: if token already exists, do nothing.
-- Actual token generation happens in Worker on first API call / migration job.
-- We keep this migration as a no-op guard to ensure table exists before Worker writes.

-- Ensure INT-001 has a publish_state row (already done in 0002, but safe)
INSERT OR IGNORE INTO publish_state (questionnaire_id, is_published, public_link_enabled)
SELECT id, is_active, 0 FROM questionnaires WHERE questionnaire_code = 'INT-001';

-- No token auto-generated in SQL to guarantee 128-bit crypto randomness via Worker.
-- The Worker endpoint /api/admin/backfill-tokens will generate tokens securely if missing.
SELECT 1;
